453:
SELECT DISTINCT c."convertedmanacost"
FROM "cards" c
WHERE c."name" = 'Ancestor''s Chosen';

509:
SELECT s."id"
FROM "sets" AS s
WHERE s."basesetsize" = (
    SELECT MAX(s2."basesetsize")
    FROM "sets" AS s2
);

621:
SELECT DISTINCT b."name"
FROM "badges" b
WHERE b."userid" IN (
    SELECT u."id"
    FROM "users" u
    WHERE u."reputation" = (
        SELECT MIN(u2."reputation")
        FROM "users" u2
    )
);

588:
SELECT COUNT(c."id") AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT p."viewcount"
FROM "posts" AS p
WHERE p."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" AS s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT m."member_id") AS president_count
FROM "member" m
WHERE LOWER(TRIM(m."position")) = 'president';

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
    SELECT MIN("remaining") FROM "budget"
);
